{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Flavoxate, the closest benzopyrone analogue, showed absolute oral bioavailability close to 100% in healthy male volunteers, directly supporting high F for the coumarin core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Thalidomide, a small neutral aromatic heterocycle, showed probably high absolute oral bioavailability of 80-100% at low doses in fasting healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ondansetron, a heteroaromatic drug with measurable first-pass metabolism, had absolute oral bioavailability of 66.1 ± 14.4% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Fenspiride had absolute oral bioavailability of 90% in healthy volunteers, supporting high F for small orally administered drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Primidone had absolute oral bioavailability greater than 90% in humans, providing another example of high F among small heterocyclic drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues with high assay-transfer scores report absolute oral bioavailability well above 20% (56-100%), including the closest benzopyrone analogue flavoxate (~100%). The query is therefore predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coumarin itself was retrieved.",
    "Potential first-pass metabolism of the lactone core is not directly captured by the analogues, though all transferred evidence exceeds the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

